  vortex_http_request_duration_seconds_bucket{ruta, mètode, le}

mesuradors de websocket:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{habitació,usuari}

comptadors personalitzats:
  vortex_messages_sent_total{room_type}
  vortex_calls_started_total{kind}

