fts5.h1_f:
CREATE VIRTUAL TABLE messages_fts USING fts5(
  contingut, -- columna amb testimoni
  room_id UNINDEXED,
  tokenize = 'unicode61 remove_diacritics 2'
);
consulta: SELECT rowid FROM messages_fts WHERE contingut MATCH 'foo'

